23559", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2505.23559", "doi": null, "is_oa": true, "landing_page_url": "http://arxiv.org/abs/2505.23559", "pdf_url": "https://arxiv.org/pdf/2505.23559", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "Recent advancements in large language model (LLM) agents have significantly accelerated scientific discovery automation, yet concurrently raised critical ethical and safety concerns. To systematically address these challenges, we introduce \\textbf{SafeScientist}, an innovative AI scientist framework explicitly designed to enhance safety and ethical responsibility in AI-driven scientific exploration. SafeScientist proactively refuses ethically inappropriate or high-risk tasks and rigorously emphasizes safety throughout the research process. To achieve comprehensive safety oversight, we integrate multiple defensive mechanisms, including prompt monitoring, agent-collaboration monitoring, tool-use monitoring, and an ethical reviewer component. Complementing SafeScientist, we propose \\textbf{SciSafetyBench}, a novel benchmark specifically designed to evaluate AI safety in scientific contexts, comprising 240 high-risk scientific tasks across 6 domains, alongside 30 specially designed scientific tools and 120 tool-related risk tasks. Extensive experiments demonstrate that SafeScientist significantly improves safety performance by 35\\% compared to traditional AI scientist frameworks, without compromising scientific output quality. Additionally, we rigorously validate the robustness of our safety pipeline against diverse adversarial attack methods, further confirming the effectiveness of our integrated approach. The code and data will be available at https://github.com/ulab-uiuc/SafeScientist. \\textcolor{red}{Warning: this paper contains example data that may be offensive or harmful.}"}]", "excerpt_truncated": true, "source_sha256": "db405ddeeb60658e804b6b77071311be5095563676789f18b711b33f5f5fc093", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["openalex:W7155245490", "arxiv:2604.16922", "arxiv:2505.23559"], "source_candidates": ["https://arxiv.org/pdf/2604.16922", "https://arxiv.org/abs/2604.16922", "https://arxiv.org/pdf/2505.23559"], "source_candidate_identities": {}}

